"""`.Position Face overlay`: generated by export_nodes.py from library.blend; kept by hand from then on."""

NAME = '.Position Face overlay'
KIND = 'ShaderNodeTree'


def build(lib):
    t = lib.new_group(NAME, KIND, props={})

    t.socket('OUTPUT', 'Overlay 1 position', 'NodeSocketVector', min_value=0.0, max_value=0.0)
    t.socket('OUTPUT', 'Overlay 2 position', 'NodeSocketVector', min_value=0.0, max_value=0.0)
    t.socket('OUTPUT', 'Overlay 3 position', 'NodeSocketVector', min_value=0.0, max_value=0.0)

    t.node('NodeFrame', 'Frame.004', props={
        'location': (341.0, -55.0),
        'width': 295.2865,
        'height': 277.0,
        'label': 'Overlay 1 position',
        'use_custom_color': True,
        'color': (0.14992589, 0.39358228, 0.6018082),
    })
    t.node('NodeFrame', 'Frame.005', props={
        'location': (344.0, -343.0),
        'width': 295.2865,
        'height': 277.0,
        'label': 'Overlay 2 position',
        'use_custom_color': True,
        'color': (0.14992589, 0.39358228, 0.6018082),
    })
    t.node('NodeFrame', 'Frame.006', props={
        'location': (337.0, -633.0),
        'width': 295.2865,
        'height': 277.0,
        'label': 'Overlay 3 position',
        'use_custom_color': True,
        'color': (0.14992589, 0.39358228, 0.6018082),
    })
    t.node('ShaderNodeGroup', 'Group.002', parent='Frame.004', inputs={'Scale X': 15.0, 'Scale Y': 15.0, 'Position X': 18.5, 'Position Y': 18.5}, props={
        'node_tree': lib.group('Scale Vector'),
        'location': (30.072693, -40.20125),
        'width': 235.28653,
    })
    t.node('ShaderNodeGroup', 'Group.003', parent='Frame.005', inputs={'Scale X': 15.0, 'Scale Y': 15.0, 'Position X': 30.5, 'Position Y': 18.5}, props={
        'node_tree': lib.group('Scale Vector'),
        'location': (30.210632, -40.078003),
        'width': 235.28653,
    })
    t.node('ShaderNodeGroup', 'Group.004', parent='Frame.006', inputs={'Scale X': 15.0, 'Scale Y': 15.0, 'Position X': 20.0, 'Position Y': 18.5}, props={
        'node_tree': lib.group('Scale Vector'),
        'location': (29.93451, -40.02588),
        'width': 235.28653,
    })
    t.node('NodeReroute', 'Reroute', props={
        'location': (233.8909, -467.9927),
        'socket_idname': 'NodeSocketVector',
    })
    t.node('ShaderNodeTexCoord', 'Texture Coordinate', hide_outputs=('Generated', 'Normal', 'Object', 'Camera', 'Window', 'Reflection'), props={
        'location': (23.323795, -438.29254),
    })
    t.node('NodeGroupOutput', 'Group Output', props={
        'location': (869.16876, -249.01831),
        'width': 232.78789,
    })

    t.link('Group.002', 'Coordinates', 'Group Output', 'Overlay 1 position')
    t.link('Group.003', 'Coordinates', 'Group Output', 'Overlay 2 position')
    t.link('Group.004', 'Coordinates', 'Group Output', 'Overlay 3 position')
    t.link('Reroute', 'Output', 'Group.002', 'UV Map')
    t.link('Texture Coordinate', 'UV', 'Reroute', 'Input')
    t.link('Reroute', 'Output', 'Group.003', 'UV Map')
    t.link('Reroute', 'Output', 'Group.004', 'UV Map')
    return t
